def preparar_usuarios(apps, schema_editor):
    from django.core.management.color import no_style
    Usuario = apps.get_model("core", "Usuario")
    Usuario.objects.filter(is_superuser=True).update(rol="administrador")
    # El administrador existente conserva id=1. La nueva secuencia inicia después del máximo.
    for sql in schema_editor.connection.ops.sequence_reset_sql(no_style(), [Usuario]):
        schema_editor.execute(sql)


